referenceSolutionTemplate:
#include <iostream>
#include <thread>
using namespace std;

int bowl1 = 0;
int bowl2 = 0;

void countFirst(int n) {
    int s = 0;
    for (int i = 1; i <= n; i++) s = s + i;
    bowl1 = s;
}

void countSecond(int m) {
    int s = 0;
    for (int i = 1; i <= m; i++) s = s + i;
    bowl2 = s;
}

int main() {
    int n = 0;
    int m = 0;
    cin >> n >> m;

    thread t1(countFirst, n);
    thread t2(countSecond, m);
    t1.join();
    t2.join();

    cout << "{w1} " << bowl1 << endl;
    cout << "{w2} " << bowl2 << endl;
    cout << "一共 " << bowl1 + bowl2 << endl;
    return 0;
}
